def test_graphs_callback_registers_avg_monthly_gain_output(mock_db_handler):
    """The update_theme callback should output to avg-monthly-gain-value."""
    from flask import Flask
    import dash._callback
    flask_app = Flask(__name__)
    dash_app = create_dash_app(flask_app, mock_db_handler)

    target_found = False
    for v in dash._callback.GLOBAL_CALLBACK_MAP.values():
        if not (isinstance(v, dict) and 'callback' in v):
            continue
        if v['callback'].__name__ != 'update_theme':
            continue
        outputs = v.get('output') or []
        if not isinstance(outputs, list):
            outputs = [outputs]
        for o in outputs:
            # Output object str repr is like: <Output `avg-monthly-gain-value.children`>
            s = str(o)
            if 'avg-monthly-gain-value' in s and 'children' in s:
                target_found = True
                break
        if target_found:
            break
    assert target_found, "update_theme callback should output to avg-monthly-gain-value.children"

